-- Provider-neutral records only. No charges, payment success or processor choice.
BEGIN;
CREATE TABLE public.sandy_commerce_contracts(operation text PRIMARY KEY,contract jsonb NOT NULL);
CREATE TABLE public.sandy_commerce_results(admission_id uuid PRIMARY KEY REFERENCES public.sandy_api_execution_admissions(id),result jsonb NOT NULL,executed boolean,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_commerce_configuration(customer_id uuid PRIMARY KEY REFERENCES public.email_customers(id) ON DELETE RESTRICT,currency text NOT NULL CHECK(currency~'^[A-Z]{3}$'),minor_unit_exponent integer NOT NULL CHECK(minor_unit_exponent BETWEEN 0 AND 3),invoice_prefix text NOT NULL CHECK(invoice_prefix~'^[A-Z0-9-]{1,16}$'),next_invoice_number bigint NOT NULL DEFAULT 1 CHECK(next_invoice_number>0),default_terms_days integer NOT NULL CHECK(default_terms_days BETWEEN 0 AND 365),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_commerce_consents(customer_id uuid PRIMARY KEY REFERENCES public.email_customers(id) ON DELETE RESTRICT,terms_version text NOT NULL,invoice_forwarding_allowed boolean NOT NULL DEFAULT false,automatic_renewal_recorded boolean NOT NULL DEFAULT false,expires_at timestamptz NOT NULL,revoked_at timestamptz,revision integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_commerce_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES public.email_customers(id) ON DELETE RESTRICT,code text NOT NULL,name text NOT NULL,kind text NOT NULL CHECK(kind IN('asset','liability','equity','income','expense')),currency text NOT NULL,minor_unit_exponent integer NOT NULL,active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(customer_id,code));
CREATE TABLE public.sandy_commerce_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES public.email_customers(id) ON DELETE RESTRICT,description text NOT NULL,external_reference text NOT NULL,effective_at timestamptz NOT NULL,state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','posted')),currency text NOT NULL,minor_unit_exponent integer NOT NULL,version integer NOT NULL DEFAULT 1,reversal_of uuid UNIQUE REFERENCES public.sandy_commerce_entries(id) ON DELETE RESTRICT,posted_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_commerce_entry_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entry_id uuid NOT NULL REFERENCES public.sandy_commerce_entries(id) ON DELETE CASCADE,account_id uuid NOT NULL REFERENCES public.sandy_commerce_accounts(id) ON DELETE RESTRICT,debit_minor bigint NOT NULL CHECK(debit_minor>=0),credit_minor bigint NOT NULL CHECK(credit_minor>=0),description text NOT NULL DEFAULT '',CHECK((debit_minor>0 AND credit_minor=0)OR(credit_minor>0 AND debit_minor=0)));
CREATE TABLE public.sandy_commerce_statements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES public.email_customers(id) ON DELETE RESTRICT,account_id uuid NOT NULL REFERENCES public.sandy_commerce_accounts(id) ON DELETE RESTRICT,source_reference text NOT NULL,source_kind text NOT NULL DEFAULT 'manual_unverified' CHECK(source_kind='manual_unverified'),content_sha256 text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(customer_id,account_id,source_reference));
CREATE TABLE public.sandy_commerce_statement_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),statement_id uuid NOT NULL REFERENCES public.sandy_commerce_statements(id) ON DELETE CASCADE,external_reference text NOT NULL,effective_at timestamptz NOT NULL,amount_minor bigint NOT NULL,description text NOT NULL DEFAULT '',UNIQUE(statement_id,external_reference));
CREATE TABLE public.sandy_commerce_reconciliations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES public.email_customers(id) ON DELETE RESTRICT,statement_id uuid NOT NULL REFERENCES public.sandy_commerce_statements(id) ON DELETE RESTRICT,state text NOT NULL DEFAULT 'proposed_internal' CHECK(state IN('proposed_internal','reviewed_internal')),matches jsonb NOT NULL,version integer NOT NULL DEFAULT 1,reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_commerce_invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES public.email_customers(id) ON DELETE RESTRICT,counterparty_name text NOT NULL,external_reference text NOT NULL,currency text NOT NULL,minor_unit_exponent integer NOT NULL,items jsonb NOT NULL,subtotal_minor numeric(30,0) NOT NULL,tax_minor bigint NOT NULL CHECK(tax_minor>=0),discount_minor bigint NOT NULL CHECK(discount_minor>=0),total_minor numeric(30,0) NOT NULL CHECK(total_minor>=0),due_at timestamptz NOT NULL,state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','issued_internal','void')),invoice_number text,version integer NOT NULL DEFAULT 1,source_message_id uuid REFERENCES public.email_messages(id) ON DELETE RESTRICT,forwarding_status text NOT NULL DEFAULT 'not_observed' CHECK(forwarding_status IN('not_observed','claimed','sending','submitted','verified','needs_review','failed','unknown')),payment_status text NOT NULL DEFAULT 'unverified' CHECK(payment_status='unverified'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(customer_id,invoice_number));
CREATE TABLE public.sandy_commerce_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,name text NOT NULL,description text NOT NULL,active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_commerce_prices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),plan_id uuid NOT NULL REFERENCES public.sandy_commerce_plans(id) ON DELETE RESTRICT,currency text NOT NULL,minor_unit_exponent integer NOT NULL CHECK(minor_unit_exponent BETWEEN 0 AND 3),unit_minor bigint NOT NULL CHECK(unit_minor>=0),interval text NOT NULL CHECK(interval IN('one_time','month','year')),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_commerce_entitlements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES public.email_customers(id) ON DELETE RESTRICT,feature_key text NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,reason text NOT NULL,version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(customer_id,feature_key));
CREATE TABLE public.sandy_commerce_effects(admission_id uuid PRIMARY KEY REFERENCES public.sandy_api_execution_admissions(id) ON DELETE RESTRICT,customer_id uuid REFERENCES public.email_customers(id) ON DELETE RESTRICT,operation text NOT NULL,actor_kind text NOT NULL CHECK(actor_kind IN('owner','tenant')),created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX sandy_commerce_entries_customer_idx ON public.sandy_commerce_entries(customer_id,id);
CREATE INDEX sandy_commerce_lines_account_idx ON public.sandy_commerce_entry_lines(account_id,entry_id);
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['sandy_commerce_contracts','sandy_commerce_results','sandy_commerce_configuration','sandy_commerce_consents','sandy_commerce_accounts','sandy_commerce_entries','sandy_commerce_entry_lines','sandy_commerce_statements','sandy_commerce_statement_lines','sandy_commerce_reconciliations','sandy_commerce_invoices','sandy_commerce_plans','sandy_commerce_prices','sandy_commerce_entitlements','sandy_commerce_effects'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated,service_role',t);END LOOP;END $$;
CREATE FUNCTION public.sandy_commerce_principal(p_operation text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE config jsonb;principal jsonb;
BEGIN
 SELECT contract INTO config FROM public.sandy_commerce_contracts WHERE operation=p_operation;IF config IS NULL THEN RETURN NULL;END IF;
 principal:=public.sandy_product_principal(CASE WHEN config->>'authorization'='owner' THEN 'product.configuration.providers.get' ELSE 'customer.profile.get' END);
 IF principal IS NULL OR config->>'authorization'='owner' AND NOT public.sandy_api_current_owner((principal->>'actor_id')::uuid) OR config->>'authorization'='portal' AND principal->>'tenant_id' IS NULL THEN RETURN NULL;END IF;RETURN principal;
END $$;
CREATE FUNCTION public.sandy_commerce_minor(p_value text,p_signed boolean DEFAULT false) RETURNS bigint LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
BEGIN IF p_value IS NULL OR p_value !~ (CASE WHEN p_signed THEN '^-?(0|[1-9][0-9]{0,18})$' ELSE '^(0|[1-9][0-9]{0,18})$' END) OR p_value::numeric NOT BETWEEN -9223372036854775807 AND 9223372036854775807 THEN RAISE EXCEPTION 'invalid_minor_unit_amount' USING ERRCODE='22003';END IF;RETURN p_value::bigint;END $$;
CREATE FUNCTION public.sandy_commerce_result(p_item jsonb DEFAULT NULL,p_items jsonb DEFAULT '[]',p_changed boolean DEFAULT false,p_cursor text DEFAULT NULL,p_truncated boolean DEFAULT false) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$SELECT jsonb_build_object('item',p_item,'items',p_items,'changed',p_changed,'next_cursor',p_cursor,'possibly_truncated',p_truncated,'source','internal_commerce_records','payment_executed',false,'provider_verified',false)$$;
CREATE FUNCTION public.sandy_commerce_entry_json(p_entry public.sandy_commerce_entries) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$SELECT to_jsonb(p_entry)-'customer_id'||jsonb_build_object('lines',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',l.id,'account_id',l.account_id,'debit_minor',l.debit_minor::text,'credit_minor',l.credit_minor::text,'description',l.description) ORDER BY l.id),'[]') FROM public.sandy_commerce_entry_lines l WHERE l.entry_id=(p_entry).id),'record_type','internal_journal','provider_verified',false)$$;
CREATE FUNCTION public.sandy_commerce_invoice_json(p_invoice public.sandy_commerce_invoices) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$SELECT to_jsonb(p_invoice)-'customer_id'||jsonb_build_object('subtotal_minor',(p_invoice).subtotal_minor::text,'tax_minor',(p_invoice).tax_minor::text,'discount_minor',(p_invoice).discount_minor::text,'total_minor',(p_invoice).total_minor::text,'tax_provenance','user_supplied_unverified','invoice_source_correspondence_verified',false,'source_linkage','customer_asserted','payment_executed',false,'provider_verified',false)$$;
CREATE FUNCTION public.sandy_commerce_statement_json(p_statement public.sandy_commerce_statements) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$SELECT to_jsonb(p_statement)-'customer_id'||jsonb_build_object('lines',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',l.id,'external_reference',l.external_reference,'effective_at',l.effective_at,'amount_minor',l.amount_minor::text,'description',l.description) ORDER BY l.id),'[]') FROM public.sandy_commerce_statement_lines l WHERE l.statement_id=(p_statement).id),'provider_verified',false)$$;
CREATE FUNCTION public.sandy_commerce_proposed_matches(p_statement public.sandy_commerce_statements) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$SELECT coalesce(jsonb_agg(jsonb_build_object('statement_line_id',l.id,'external_reference',l.external_reference,'amount_minor',l.amount_minor::text,'state',CASE WHEN c.n=1 THEN 'proposed_internal_match' WHEN c.n>1 THEN 'ambiguous' ELSE 'unmatched' END,'candidate_count',c.n,'candidate_entry_id',CASE WHEN c.n=1 THEN c.id END,'provider_verified',false) ORDER BY l.id),'[]') FROM public.sandy_commerce_statement_lines l CROSS JOIN LATERAL(SELECT count(*) AS n,min(e.id::text)::uuid AS id FROM public.sandy_commerce_entries e WHERE e.customer_id=(p_statement).customer_id AND e.state='posted' AND e.external_reference=l.external_reference AND EXISTS(SELECT 1 FROM public.sandy_commerce_entry_lines present WHERE present.entry_id=e.id AND present.account_id=(p_statement).account_id) AND(SELECT coalesce(sum(j.debit_minor::numeric-j.credit_minor::numeric),0) FROM public.sandy_commerce_entry_lines j WHERE j.entry_id=e.id AND j.account_id=(p_statement).account_id)=l.amount_minor)c WHERE l.statement_id=(p_statement).id$$;

