CREATE FUNCTION public.sandy_commerce_scope_sha(p_operation text,p_actor uuid,p_tenant uuid,p_channel text,p_contract_sha text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
 SELECT encode(extensions.digest('sandy_commerce_v1:'||p_actor::text||':'||coalesce(p_tenant::text,'owner')||':'||p_operation||':'||p_channel||':'||p_contract_sha,'sha256'),'hex')
$$;
CREATE FUNCTION public.sandy_commerce_admit(p_operation text,p_arguments jsonb,p_canonical_arguments text,p_request_id uuid,p_channel text DEFAULT 'api',p_approval_id uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE principal jsonb; config jsonb; registry public.sandy_operation_registry%ROWTYPE; prior public.sandy_api_execution_admissions%ROWTYPE; admission public.sandy_api_execution_admissions%ROWTYPE; input_hash text;scope_hash text;active_window timestamptz:=date_trunc('minute',clock_timestamp());requests integer;units integer;
BEGIN
 principal:=public.sandy_commerce_principal(p_operation); IF principal IS NULL THEN RETURN jsonb_build_object('ok',false,'error','product_identity_or_grant_required','http_status',403); END IF;
 SELECT contract INTO config FROM public.sandy_commerce_contracts WHERE operation=p_operation;
 IF p_channel IS NULL OR p_channel NOT IN ('api','mcp') OR p_request_id IS NULL OR octet_length(p_canonical_arguments)>100000 OR p_canonical_arguments::jsonb IS DISTINCT FROM p_arguments OR NOT public.sandy_product_input_valid(config->'input_schema',p_arguments) THEN RETURN jsonb_build_object('ok',false,'error','invalid_product_arguments','http_status',400); END IF;
 IF (config->>'is_mutation')::boolean AND (p_arguments->>'idempotency_key')::uuid IS DISTINCT FROM p_request_id THEN RETURN jsonb_build_object('ok',false,'error','stable_idempotency_key_required','http_status',400); END IF;
 SELECT * INTO registry FROM public.sandy_operation_registry WHERE operation=p_operation FOR SHARE;
 IF registry.handler IS DISTINCT FROM 'sandy-commerce-ledger-api' OR registry.api_exposed IS DISTINCT FROM true OR (p_channel='mcp' AND registry.ai_exposed IS DISTINCT FROM true) OR registry.error_contract->>'contract_sha256' IS DISTINCT FROM config->>'contract_sha256' OR registry.error_contract->>'requires_approval' IS DISTINCT FROM ((config->>'authorization'='owner') AND ((config->>'is_mutation')::boolean OR(config->>'sensitive')::boolean))::text OR registry.error_contract->>'api_key_delegable' IS DISTINCT FROM 'false' OR registry.is_mutation IS DISTINCT FROM (config->>'is_mutation')::boolean OR registry.input_schema IS DISTINCT FROM config->'input_schema' OR registry.output_schema IS DISTINCT FROM config->'output_schema' OR registry.permission_scope IS DISTINCT FROM (CASE WHEN config->>'authorization'='owner' THEN 'system:' ELSE 'commerce:' END||CASE WHEN (config->>'is_mutation')::boolean THEN 'write' ELSE 'read' END) THEN RETURN jsonb_build_object('ok',false,'error','product_contract_not_enabled','http_status',403); END IF;
 IF (registry.is_mutation OR (config->>'sensitive')::boolean) AND NOT registry.verified THEN RETURN jsonb_build_object('ok',false,'error','operation_requires_live_verification','http_status',424); END IF;
 input_hash:=encode(extensions.digest(p_canonical_arguments,'sha256'),'hex');scope_hash:=public.sandy_commerce_scope_sha(p_operation,(principal->>'actor_id')::uuid,(principal->>'tenant_id')::uuid,p_channel,config->>'contract_sha256');
 IF config->>'authorization'='owner' THEN
  principal:=principal||public.sandy_api_admit_execution((principal->>'actor_id')::uuid,NULL,p_operation,input_hash,p_request_id,NULL,config->>'contract_sha256',scope_hash,CASE WHEN (config->>'consumes_provider_units')::boolean THEN 1 ELSE 0 END,p_approval_id);
  IF principal->>'reused'='true' THEN principal:=principal||jsonb_build_object('receipt',(SELECT result FROM public.sandy_commerce_results WHERE admission_id=(principal->>'admission_id')::uuid),'executed',(SELECT executed FROM public.sandy_commerce_results WHERE admission_id=(principal->>'admission_id')::uuid));END IF;RETURN principal;
 END IF;
 IF principal->>'tenant_id' IS NULL THEN RETURN jsonb_build_object('ok',false,'error','product_receipt_endpoint_required','http_status',400);END IF;
 IF p_approval_id IS NOT NULL THEN RETURN jsonb_build_object('ok',false,'error','owner_approval_not_customer_session','http_status',400); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sandy-commerce:'||(principal->>'actor_id')||':'||p_request_id::text,0));
 SELECT * INTO prior FROM public.sandy_api_execution_admissions WHERE actor_id=(principal->>'actor_id')::uuid AND request_id=p_request_id;
 IF FOUND THEN
  IF prior.operation<>p_operation OR prior.tenant_id IS DISTINCT FROM (principal->>'tenant_id')::uuid OR prior.input_sha256<>input_hash OR prior.contract_sha256<>config->>'contract_sha256' OR prior.scope_sha256<>scope_hash THEN RETURN jsonb_build_object('ok',false,'error','request_id_conflict','http_status',409); END IF;
  RETURN jsonb_build_object('ok',true,'reused',true,'admission_id',prior.id,'request_id',prior.request_id,'state',prior.state,'receipt',(SELECT result FROM public.sandy_commerce_results WHERE admission_id=prior.id),'executed',coalesce((SELECT executed FROM public.sandy_commerce_results WHERE admission_id=prior.id),CASE WHEN prior.state IN ('admitted','rejected') THEN false ELSE NULL END));
 END IF;
 INSERT INTO public.sandy_api_rate_windows(actor_id,bucket,window_start,requests,declared_units) VALUES((principal->>'actor_id')::uuid,'commerce:'||(principal->>'tenant_id'),active_window,0,0) ON CONFLICT DO NOTHING;
 SELECT w.requests,w.declared_units INTO requests,units FROM public.sandy_api_rate_windows w WHERE w.actor_id=(principal->>'actor_id')::uuid AND w.bucket='commerce:'||(principal->>'tenant_id') AND w.window_start=active_window FOR UPDATE;
 IF requests>=60 OR ((config->>'consumes_provider_units')::boolean AND units>=1) THEN RETURN jsonb_build_object('ok',false,'error','product_rate_or_provider_unit_budget_exceeded','http_status',429); END IF;
 INSERT INTO public.sandy_api_execution_admissions(actor_id,tenant_id,operation,request_id,is_mutation,input_sha256,contract_sha256,scope_sha256,registry_revision_sha256,declared_cost_units,expires_at) VALUES((principal->>'actor_id')::uuid,(principal->>'tenant_id')::uuid,p_operation,p_request_id,registry.is_mutation,input_hash,config->>'contract_sha256',scope_hash,public.sandy_api_registry_revision(p_operation),CASE WHEN (config->>'consumes_provider_units')::boolean THEN 1 ELSE 0 END,clock_timestamp()+interval '60 seconds') RETURNING * INTO admission;
 UPDATE public.sandy_api_rate_windows w SET requests=w.requests+1,declared_units=w.declared_units+admission.declared_cost_units WHERE w.actor_id=admission.actor_id AND w.bucket='commerce:'||admission.tenant_id::text AND w.window_start=active_window;
 PERFORM public.sandy_api_append_audit(admission.actor_id,p_operation,p_request_id,NULL,admission.id,'admission','admitted',input_hash,NULL,NULL,NULL);
 RETURN jsonb_build_object('ok',true,'allowed',true,'reused',false,'admission_id',admission.id,'grant_id',admission.grant_id,'request_id',p_request_id,'state','admitted','executed',false,'expires_at',admission.expires_at,'actor_id',admission.actor_id,'tenant_id',admission.tenant_id,'scope_sha256',scope_hash);
EXCEPTION WHEN data_exception THEN RETURN jsonb_build_object('ok',false,'error','invalid_product_arguments','http_status',400);
END $$;
CREATE FUNCTION public.sandy_commerce_consume(p_admission_id uuid,p_grant_id uuid,p_arguments jsonb,p_canonical_arguments text,p_channel text DEFAULT 'api') RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE admission public.sandy_api_execution_admissions%ROWTYPE;principal jsonb;config jsonb; proof jsonb;registry public.sandy_operation_registry%ROWTYPE;
BEGIN
 SELECT * INTO admission FROM public.sandy_api_execution_admissions WHERE id=p_admission_id FOR UPDATE;
 IF admission.id IS NULL OR admission.actor_id IS DISTINCT FROM auth.uid() OR auth.role() IS DISTINCT FROM 'authenticated' OR admission.grant_id IS DISTINCT FROM p_grant_id OR admission.credential_id IS NOT NULL THEN RETURN jsonb_build_object('ok',false,'error','product_grant_not_found','http_status',403); END IF;
 principal:=public.sandy_commerce_principal(admission.operation);SELECT contract INTO config FROM public.sandy_commerce_contracts WHERE operation=admission.operation;
 SELECT * INTO registry FROM public.sandy_operation_registry WHERE operation=admission.operation;
 IF p_channel IS NULL OR p_channel NOT IN ('api','mcp') OR registry.handler IS DISTINCT FROM 'sandy-commerce-ledger-api' OR registry.api_exposed IS DISTINCT FROM true OR(p_channel='mcp' AND registry.ai_exposed IS DISTINCT FROM true) OR((registry.is_mutation OR(config->>'sensitive')::boolean) AND registry.verified IS DISTINCT FROM true) OR registry.error_contract->>'contract_sha256' IS DISTINCT FROM config->>'contract_sha256' OR registry.error_contract->>'requires_approval' IS DISTINCT FROM ((config->>'authorization'='owner') AND ((config->>'is_mutation')::boolean OR(config->>'sensitive')::boolean))::text OR registry.error_contract->>'api_key_delegable' IS DISTINCT FROM 'false' OR registry.input_schema IS DISTINCT FROM config->'input_schema' OR registry.output_schema IS DISTINCT FROM config->'output_schema' OR registry.permission_scope IS DISTINCT FROM (CASE WHEN config->>'authorization'='owner' THEN 'system:' ELSE 'commerce:' END||CASE WHEN (config->>'is_mutation')::boolean THEN 'write' ELSE 'read' END) THEN RETURN jsonb_build_object('ok',false,'error','product_contract_or_exposure_changed','http_status',409);END IF;
 IF principal IS NULL OR admission.actor_id IS DISTINCT FROM (principal->>'actor_id')::uuid OR admission.tenant_id IS DISTINCT FROM (principal->>'tenant_id')::uuid OR admission.state<>'admitted' OR admission.expires_at<=clock_timestamp() OR admission.input_sha256<>encode(extensions.digest(p_canonical_arguments,'sha256'),'hex') OR p_canonical_arguments::jsonb IS DISTINCT FROM p_arguments OR NOT public.sandy_product_input_valid(config->'input_schema',p_arguments) OR admission.scope_sha256<>public.sandy_commerce_scope_sha(admission.operation,admission.actor_id,admission.tenant_id,p_channel,admission.contract_sha256) OR admission.registry_revision_sha256 IS DISTINCT FROM public.sandy_api_registry_revision(admission.operation) THEN RETURN jsonb_build_object('ok',false,'error','product_grant_used_expired_or_changed','http_status',409); END IF;
 IF config->>'authorization'='owner' THEN
  proof:=public.sandy_api_consume_execution_grant(p_grant_id,admission.actor_id,NULL,admission.operation,admission.input_sha256,admission.request_id,admission.contract_sha256,admission.scope_sha256);
  IF proof->>'allowed' IS DISTINCT FROM 'true' THEN RETURN proof; END IF;
 ELSE
  UPDATE public.sandy_api_execution_admissions SET state='consumed',consumed_at=clock_timestamp() WHERE id=admission.id;
  PERFORM public.sandy_api_append_audit(admission.actor_id,admission.operation,admission.request_id,NULL,admission.id,'dispatch','consumed',admission.input_sha256,NULL,NULL,NULL);
 END IF;
 RETURN jsonb_build_object('ok',true,'admission_id',admission.id,'operation',admission.operation,'actor_id',admission.actor_id,'tenant_id',admission.tenant_id,'request_id',admission.request_id);
EXCEPTION WHEN data_exception THEN RETURN jsonb_build_object('ok',false,'error','invalid_product_arguments','http_status',400);
END $$;

CREATE FUNCTION public.sandy_commerce_replace_lines(p_entry_id uuid,p_customer_id uuid,p_lines jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE entry public.sandy_commerce_entries%ROWTYPE;a public.sandy_commerce_accounts%ROWTYPE;line jsonb;
BEGIN
 SELECT * INTO entry FROM public.sandy_commerce_entries WHERE id=p_entry_id AND customer_id=p_customer_id FOR UPDATE;IF entry.id IS NULL OR entry.state<>'draft' THEN RAISE EXCEPTION 'journal_not_editable' USING ERRCODE='P0409';END IF;
 PERFORM 1 FROM public.sandy_commerce_accounts WHERE id IN(SELECT(value->>'account_id')::uuid FROM jsonb_array_elements(p_lines)) ORDER BY id FOR SHARE;
 DELETE FROM public.sandy_commerce_entry_lines WHERE entry_id=entry.id;
 FOR line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
  SELECT * INTO a FROM public.sandy_commerce_accounts WHERE id=(line->>'account_id')::uuid AND customer_id=p_customer_id AND active AND currency=entry.currency AND minor_unit_exponent=entry.minor_unit_exponent;
  IF a.id IS NULL THEN RAISE EXCEPTION 'owned_active_same_currency_account_required' USING ERRCODE='P0409';END IF;
  INSERT INTO public.sandy_commerce_entry_lines(entry_id,account_id,debit_minor,credit_minor,description) VALUES(entry.id,a.id,public.sandy_commerce_minor(line->>'debit_minor'),public.sandy_commerce_minor(line->>'credit_minor'),coalesce(line->>'description',''));
 END LOOP;
END $$;
CREATE FUNCTION public.sandy_commerce_invoice_totals(p_items jsonb,p_tax text,p_discount text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
DECLARE item jsonb;subtotal numeric:=0;tax bigint:=public.sandy_commerce_minor(p_tax);discount bigint:=public.sandy_commerce_minor(p_discount);
BEGIN FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP subtotal:=subtotal+(item->>'quantity')::integer*public.sandy_commerce_minor(item->>'unit_minor')::numeric;END LOOP;IF discount>subtotal THEN RAISE EXCEPTION 'discount_exceeds_subtotal' USING ERRCODE='22023';END IF;RETURN jsonb_build_object('subtotal_minor',subtotal::text,'tax_minor',tax::text,'discount_minor',discount::text,'total_minor',(subtotal+tax-discount)::text);END $$;
CREATE FUNCTION public.sandy_commerce_guard_posted_entry() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$BEGIN IF OLD.state='posted' THEN RAISE EXCEPTION 'posted_journal_is_immutable_use_reversal' USING ERRCODE='23514';END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;
CREATE TRIGGER sandy_commerce_posted_entry_guard BEFORE UPDATE OR DELETE ON public.sandy_commerce_entries FOR EACH ROW EXECUTE FUNCTION public.sandy_commerce_guard_posted_entry();
CREATE FUNCTION public.sandy_commerce_guard_posted_line() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
BEGIN IF EXISTS(SELECT 1 FROM public.sandy_commerce_entries WHERE id=CASE WHEN TG_OP='DELETE' THEN OLD.entry_id ELSE NEW.entry_id END AND state='posted') OR(TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.sandy_commerce_entries WHERE id=OLD.entry_id AND state='posted')) THEN RAISE EXCEPTION 'posted_journal_lines_are_immutable' USING ERRCODE='23514';END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;
CREATE TRIGGER sandy_commerce_posted_line_guard BEFORE INSERT OR UPDATE OR DELETE ON public.sandy_commerce_entry_lines FOR EACH ROW EXECUTE FUNCTION public.sandy_commerce_guard_posted_line();
CREATE FUNCTION public.sandy_commerce_guard_issued_invoice() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
BEGIN IF OLD.state IN('issued_internal','void') AND(NEW.counterparty_name IS DISTINCT FROM OLD.counterparty_name OR NEW.external_reference IS DISTINCT FROM OLD.external_reference OR NEW.currency IS DISTINCT FROM OLD.currency OR NEW.minor_unit_exponent IS DISTINCT FROM OLD.minor_unit_exponent OR NEW.items IS DISTINCT FROM OLD.items OR NEW.subtotal_minor IS DISTINCT FROM OLD.subtotal_minor OR NEW.tax_minor IS DISTINCT FROM OLD.tax_minor OR NEW.discount_minor IS DISTINCT FROM OLD.discount_minor OR NEW.total_minor IS DISTINCT FROM OLD.total_minor OR NEW.due_at IS DISTINCT FROM OLD.due_at OR NEW.invoice_number IS DISTINCT FROM OLD.invoice_number OR NEW.state NOT IN('issued_internal','void')) THEN RAISE EXCEPTION 'issued_invoice_values_are_immutable' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER sandy_commerce_issued_invoice_guard BEFORE UPDATE ON public.sandy_commerce_invoices FOR EACH ROW EXECUTE FUNCTION public.sandy_commerce_guard_issued_invoice();

-- A legitimate input fits100KB. Bound every returned page independently of row
-- count, leaving ample room beneath the600KB HTTP transport ceiling. The cursor
-- always names the last returned record; never silently skip a trimmed record.
CREATE FUNCTION public.sandy_commerce_bounded_result(p_item jsonb,p_items jsonb,p_changed boolean,p_cursor text,p_truncated boolean) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
DECLARE items jsonb:=p_items;result jsonb;cursor text:=p_cursor;trimmed boolean:=false;
BEGIN
 result:=public.sandy_commerce_result(p_item,items,p_changed,cursor,p_truncated);
 WHILE octet_length(result::text)>192000 AND jsonb_array_length(items)>0 LOOP
  items:=items-(jsonb_array_length(items)-1);trimmed:=true;
  cursor:=CASE WHEN jsonb_array_length(items)>0 THEN items->-1->>'id' END;
  result:=public.sandy_commerce_result(p_item,items,p_changed,cursor,true);
 END LOOP;
 IF octet_length(result::text)>192000 OR(trimmed AND jsonb_array_length(items)=0) THEN RAISE EXCEPTION 'commerce_single_record_response_too_large' USING ERRCODE='P0413';END IF;
 RETURN result;
END $$;

-- Known internal failures roll back the entire workflow subtransaction first.
-- Reconsume the still-current original proof and persist a terminal unexecuted
-- receipt; no provider HTTP status or financial effect is fabricated.
CREATE FUNCTION public.sandy_commerce_fail_internal(p_admission_id uuid,p_grant_id uuid,p_arguments jsonb,p_canonical_arguments text,p_channel text,p_error text,p_http_status integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;admission public.sandy_api_execution_admissions%ROWTYPE;result jsonb;
BEGIN
 proof:=public.sandy_commerce_consume(p_admission_id,p_grant_id,p_arguments,p_canonical_arguments,p_channel);IF proof->>'ok' IS DISTINCT FROM 'true' THEN RETURN proof;END IF;
 SELECT * INTO admission FROM public.sandy_api_execution_admissions WHERE id=p_admission_id;
 result:=public.sandy_commerce_result(jsonb_build_object('error',p_error,'internal_effect_committed',false));
 proof:=public.sandy_api_finish_execution(admission.id,'failed',NULL,NULL,encode(extensions.digest(result::text,'sha256'),'hex'));IF proof->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'commerce_failure_receipt_not_persisted';END IF;
 INSERT INTO public.sandy_commerce_results VALUES(admission.id,result,false,clock_timestamp());
 RETURN jsonb_build_object('ok',false,'error',p_error,'http_status',p_http_status,'admission_id',admission.id,'request_id',admission.request_id,'executed',false,'reconciliation_required',false);
END $$;
CREATE FUNCTION public.sandy_commerce_execute(p_admission_id uuid,p_grant_id uuid,p_arguments jsonb,p_canonical_arguments text,p_channel text DEFAULT 'api') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;admission public.sandy_api_execution_admissions%ROWTYPE;config jsonb;op text;tenant uuid;effect_tenant uuid;item jsonb;items jsonb:='[]';before_row jsonb;result jsonb;changed boolean:=false;cursor text;lim integer:=coalesce((p_arguments->>'limit')::integer,50);cfg public.sandy_commerce_configuration%ROWTYPE;account public.sandy_commerce_accounts%ROWTYPE;entry public.sandy_commerce_entries%ROWTYPE;original public.sandy_commerce_entries%ROWTYPE;statement public.sandy_commerce_statements%ROWTYPE;recon public.sandy_commerce_reconciliations%ROWTYPE;invoice public.sandy_commerce_invoices%ROWTYPE;plan public.sandy_commerce_plans%ROWTYPE;price public.sandy_commerce_prices%ROWTYPE;consent public.sandy_commerce_consents%ROWTYPE;line jsonb;totals jsonb;debits numeric;credits numeric;line_count integer;forward_state text;field text;
BEGIN
 proof:=public.sandy_commerce_consume(p_admission_id,p_grant_id,p_arguments,p_canonical_arguments,p_channel);IF proof->>'ok' IS DISTINCT FROM 'true' THEN RETURN proof;END IF;
 SELECT * INTO admission FROM public.sandy_api_execution_admissions WHERE id=p_admission_id;op:=admission.operation;tenant:=admission.tenant_id;effect_tenant:=tenant;SELECT contract INTO config FROM public.sandy_commerce_contracts WHERE operation=op;
 IF admission.is_mutation THEN PERFORM pg_advisory_xact_lock(hashtextextended('sandy-commerce-state:'||coalesce(tenant::text,'owner'),0));END IF;
 FOR field IN SELECT unnest(ARRAY['name','description','counterparty_name','external_reference','source_reference']) LOOP IF p_arguments ? field AND length(btrim(p_arguments->>field))=0 THEN RAISE EXCEPTION 'empty_commerce_field' USING ERRCODE='22023';END IF;END LOOP;
 SELECT * INTO cfg FROM public.sandy_commerce_configuration WHERE customer_id=tenant;
 IF op='commerce.configuration.get' THEN item:=CASE WHEN cfg.customer_id IS NULL THEN jsonb_build_object('configured',false,'version',0,'processor',NULL) ELSE to_jsonb(cfg)-'customer_id'||jsonb_build_object('configured',true,'next_invoice_number',cfg.next_invoice_number::text,'processor',NULL) END;
 ELSIF op='commerce.configuration.update' THEN
  IF coalesce(cfg.version,0)<>(p_arguments->>'expected_version')::integer THEN RAISE EXCEPTION 'configuration_version_changed' USING ERRCODE='P0409';END IF;
  IF cfg.customer_id IS NOT NULL AND(cfg.currency<>p_arguments->>'currency' OR cfg.minor_unit_exponent<>(p_arguments->>'minor_unit_exponent')::integer) AND(EXISTS(SELECT 1 FROM public.sandy_commerce_accounts WHERE customer_id=tenant)OR EXISTS(SELECT 1 FROM public.sandy_commerce_invoices WHERE customer_id=tenant)) THEN RAISE EXCEPTION 'existing_records_lock_currency_units' USING ERRCODE='P0409';END IF;
  before_row:=CASE WHEN cfg.customer_id IS NULL THEN NULL ELSE to_jsonb(cfg)-'customer_id' END;
  INSERT INTO public.sandy_commerce_configuration(customer_id,currency,minor_unit_exponent,invoice_prefix,default_terms_days) VALUES(tenant,p_arguments->>'currency',(p_arguments->>'minor_unit_exponent')::integer,p_arguments->>'invoice_prefix',(p_arguments->>'default_terms_days')::integer) ON CONFLICT(customer_id) DO UPDATE SET currency=excluded.currency,minor_unit_exponent=excluded.minor_unit_exponent,invoice_prefix=excluded.invoice_prefix,default_terms_days=excluded.default_terms_days,version=sandy_commerce_configuration.version+1,updated_at=clock_timestamp() RETURNING to_jsonb(sandy_commerce_configuration.*)-'customer_id'||jsonb_build_object('next_invoice_number',sandy_commerce_configuration.next_invoice_number::text,'processor',NULL) INTO item;changed:=true;
 ELSIF op LIKE 'commerce.consent.%' THEN
  SELECT * INTO consent FROM public.sandy_commerce_consents WHERE customer_id=tenant FOR UPDATE;before_row:=CASE WHEN consent.customer_id IS NULL THEN NULL ELSE to_jsonb(consent)-'customer_id' END;
  IF op='commerce.consent.set' THEN
   IF(p_arguments->>'expires_at')::timestamptz<=clock_timestamp() OR(p_arguments->>'expires_at')::timestamptz>clock_timestamp()+interval '366 days' THEN RAISE EXCEPTION 'bounded_future_commerce_consent_required' USING ERRCODE='22023';END IF;
   INSERT INTO public.sandy_commerce_consents(customer_id,terms_version,invoice_forwarding_allowed,automatic_renewal_recorded,expires_at) VALUES(tenant,p_arguments->>'terms_version',(p_arguments->>'invoice_forwarding_allowed')::boolean,(p_arguments->>'automatic_renewal_recorded')::boolean,(p_arguments->>'expires_at')::timestamptz) ON CONFLICT(customer_id) DO UPDATE SET terms_version=excluded.terms_version,invoice_forwarding_allowed=excluded.invoice_forwarding_allowed,automatic_renewal_recorded=excluded.automatic_renewal_recorded,expires_at=excluded.expires_at,revoked_at=NULL,revision=sandy_commerce_consents.revision+1,updated_at=clock_timestamp();changed:=true;
  ELSIF op='commerce.consent.revoke' THEN UPDATE public.sandy_commerce_consents SET revoked_at=coalesce(revoked_at,clock_timestamp()),invoice_forwarding_allowed=false,automatic_renewal_recorded=false,revision=revision+1,updated_at=clock_timestamp() WHERE customer_id=tenant;changed:=FOUND;END IF;
  SELECT to_jsonb(c)-'customer_id'||jsonb_build_object('record_current',c.revoked_at IS NULL AND c.expires_at>clock_timestamp(),'authorizes_processor_charge',false,'terms_validated',false) INTO item FROM public.sandy_commerce_consents c WHERE customer_id=tenant;IF item IS NULL THEN item:=jsonb_build_object('record_current',false,'terms_validated',false,'revision',0,'invoice_forwarding_allowed',false,'automatic_renewal_recorded',false,'authorizes_processor_charge',false,'terms_validated',false);END IF;
 ELSIF op LIKE 'commerce.accounts.%' THEN
  IF op='commerce.accounts.create' THEN IF cfg.customer_id IS NULL THEN RAISE EXCEPTION 'commerce_configuration_required' USING ERRCODE='P0424';END IF;INSERT INTO public.sandy_commerce_accounts(customer_id,code,name,kind,currency,minor_unit_exponent) VALUES(tenant,p_arguments->>'code',btrim(p_arguments->>'name'),p_arguments->>'kind',cfg.currency,cfg.minor_unit_exponent) RETURNING * INTO account;changed:=true;
  ELSIF op='commerce.accounts.list' THEN SELECT coalesce(jsonb_agg(to_jsonb(q)-'customer_id' ORDER BY q.id),'[]') INTO items FROM(SELECT * FROM public.sandy_commerce_accounts WHERE customer_id=tenant AND(p_arguments->>'search' IS NULL OR strpos(lower(code||' '||name),lower(p_arguments->>'search'))>0) AND(p_arguments->>'kind' IS NULL OR kind=p_arguments->>'kind') AND(p_arguments->>'active' IS NULL OR active=(p_arguments->>'active')::boolean) AND(p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) ORDER BY id LIMIT lim)q;
  ELSE SELECT * INTO account FROM public.sandy_commerce_accounts WHERE id=(p_arguments->>'account_id')::uuid AND customer_id=tenant FOR UPDATE;IF account.id IS NULL THEN RAISE EXCEPTION 'commerce_resource_not_found' USING ERRCODE='P0404';END IF;before_row:=to_jsonb(account)-'customer_id';
   IF op IN('commerce.accounts.update','commerce.accounts.close') THEN IF account.version<>(p_arguments->>'expected_version')::integer THEN RAISE EXCEPTION 'account_version_changed' USING ERRCODE='P0409';END IF;UPDATE public.sandy_commerce_accounts SET name=coalesce(p_arguments->>'name',name),active=CASE WHEN op='commerce.accounts.close' THEN false ELSE active END,version=version+1,updated_at=clock_timestamp() WHERE id=account.id RETURNING * INTO account;changed:=true;END IF;
  END IF;IF account.id IS NOT NULL THEN item:=to_jsonb(account)-'customer_id';END IF;
 ELSIF op LIKE 'commerce.entries.%' THEN
  IF op='commerce.entries.list' THEN SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO items FROM(SELECT id,description,external_reference,effective_at,state,currency,minor_unit_exponent,version,reversal_of,posted_at,created_at,updated_at FROM public.sandy_commerce_entries WHERE customer_id=tenant AND(p_arguments->>'search' IS NULL OR strpos(lower(description||' '||external_reference),lower(p_arguments->>'search'))>0) AND(p_arguments->>'state' IS NULL OR state=p_arguments->>'state') AND(p_arguments->>'from_at' IS NULL OR effective_at>=(p_arguments->>'from_at')::timestamptz) AND(p_arguments->>'to_at' IS NULL OR effective_at<=(p_arguments->>'to_at')::timestamptz) AND(p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) ORDER BY id LIMIT lim)q;
  ELSIF op='commerce.entries.create' THEN
   IF cfg.customer_id IS NULL THEN RAISE EXCEPTION 'commerce_configuration_required' USING ERRCODE='P0424';END IF;INSERT INTO public.sandy_commerce_entries(customer_id,description,external_reference,effective_at,currency,minor_unit_exponent) VALUES(tenant,p_arguments->>'description',p_arguments->>'external_reference',(p_arguments->>'effective_at')::timestamptz,cfg.currency,cfg.minor_unit_exponent) RETURNING * INTO entry;PERFORM public.sandy_commerce_replace_lines(entry.id,tenant,p_arguments->'lines');changed:=true;
  ELSE
   SELECT * INTO entry FROM public.sandy_commerce_entries WHERE id=(p_arguments->>'entry_id')::uuid AND customer_id=tenant FOR UPDATE;IF entry.id IS NULL THEN RAISE EXCEPTION 'commerce_resource_not_found' USING ERRCODE='P0404';END IF;before_row:=public.sandy_commerce_entry_json(entry);
   IF op IN('commerce.entries.update','commerce.entries.delete','commerce.entries.post') THEN
    IF entry.state<>'draft' OR entry.version<>(p_arguments->>'expected_version')::integer THEN RAISE EXCEPTION 'journal_state_or_version_changed' USING ERRCODE='P0409';END IF;
    IF op='commerce.entries.update' THEN PERFORM public.sandy_commerce_replace_lines(entry.id,tenant,p_arguments->'lines');UPDATE public.sandy_commerce_entries SET description=p_arguments->>'description',external_reference=p_arguments->>'external_reference',effective_at=(p_arguments->>'effective_at')::timestamptz,version=version+1,updated_at=clock_timestamp() WHERE id=entry.id RETURNING * INTO entry;
    ELSIF op='commerce.entries.delete' THEN DELETE FROM public.sandy_commerce_entries WHERE id=entry.id;item:=jsonb_build_object('id',entry.id,'state','deleted_draft');entry.id:=NULL;
    ELSE
     SELECT sum(debit_minor::numeric),sum(credit_minor::numeric),count(*) INTO debits,credits,line_count FROM public.sandy_commerce_entry_lines WHERE entry_id=entry.id;
     IF line_count<2 OR debits IS NULL OR debits<>credits OR debits<=0 OR EXISTS(SELECT 1 FROM public.sandy_commerce_entry_lines l JOIN public.sandy_commerce_accounts a ON a.id=l.account_id WHERE l.entry_id=entry.id AND(NOT a.active OR a.customer_id<>tenant OR a.currency<>entry.currency OR a.minor_unit_exponent<>entry.minor_unit_exponent)) THEN RAISE EXCEPTION 'balanced_owned_active_journal_required' USING ERRCODE='P0409';END IF;
     UPDATE public.sandy_commerce_entries SET state='posted',posted_at=clock_timestamp(),version=version+1,updated_at=clock_timestamp() WHERE id=entry.id RETURNING * INTO entry;
    END IF;changed:=true;
   ELSIF op='commerce.entries.reverse' THEN
    IF entry.state<>'posted' OR EXISTS(SELECT 1 FROM public.sandy_commerce_entries WHERE reversal_of=entry.id) THEN RAISE EXCEPTION 'posted_unreversed_journal_required' USING ERRCODE='P0409';END IF;original:=entry;
    INSERT INTO public.sandy_commerce_entries(customer_id,description,external_reference,effective_at,currency,minor_unit_exponent,reversal_of) VALUES(tenant,p_arguments->>'description','reversal:'||original.id::text,(p_arguments->>'effective_at')::timestamptz,original.currency,original.minor_unit_exponent,original.id) RETURNING * INTO entry;
    INSERT INTO public.sandy_commerce_entry_lines(entry_id,account_id,debit_minor,credit_minor,description) SELECT entry.id,account_id,credit_minor,debit_minor,'Reversal of internal journal '||original.id::text FROM public.sandy_commerce_entry_lines WHERE entry_id=original.id;
    UPDATE public.sandy_commerce_entries SET state='posted',posted_at=clock_timestamp(),version=version+1,updated_at=clock_timestamp() WHERE id=entry.id RETURNING * INTO entry;changed:=true;
   END IF;
  END IF;IF entry.id IS NOT NULL THEN item:=public.sandy_commerce_entry_json(entry);END IF;
 ELSIF op IN('commerce.reports.trial_balance','commerce.reports.income_expense') THEN
  SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO items FROM(SELECT a.id,a.code,a.name,a.kind,a.currency,a.minor_unit_exponent,coalesce(sum(CASE WHEN e.id IS NOT NULL THEN l.debit_minor::numeric-l.credit_minor::numeric ELSE 0 END),0)::text AS recorded_balance_minor,false AS provider_verified FROM public.sandy_commerce_accounts a LEFT JOIN public.sandy_commerce_entry_lines l ON l.account_id=a.id LEFT JOIN public.sandy_commerce_entries e ON e.id=l.entry_id AND e.customer_id=tenant AND e.state='posted' AND(p_arguments->>'as_of' IS NULL OR e.effective_at<=(p_arguments->>'as_of')::timestamptz) AND(p_arguments->>'from_at' IS NULL OR e.effective_at>=(p_arguments->>'from_at')::timestamptz) AND(p_arguments->>'to_at' IS NULL OR e.effective_at<=(p_arguments->>'to_at')::timestamptz) WHERE a.customer_id=tenant AND(op<>'commerce.reports.income_expense' OR a.kind IN('income','expense')) AND(p_arguments->>'after_id' IS NULL OR a.id>(p_arguments->>'after_id')::uuid) GROUP BY a.id ORDER BY a.id LIMIT lim)q;
 ELSIF op='commerce.reports.account_ledger' THEN
  IF NOT EXISTS(SELECT 1 FROM public.sandy_commerce_accounts WHERE id=(p_arguments->>'account_id')::uuid AND customer_id=tenant) THEN RAISE EXCEPTION 'commerce_resource_not_found' USING ERRCODE='P0404';END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO items FROM(SELECT l.id,l.entry_id,e.external_reference,e.effective_at,l.description,l.debit_minor::text,l.credit_minor::text,(l.debit_minor::numeric-l.credit_minor::numeric)::text AS recorded_delta_minor,e.currency,e.minor_unit_exponent,false AS provider_verified FROM public.sandy_commerce_entry_lines l JOIN public.sandy_commerce_entries e ON e.id=l.entry_id WHERE e.customer_id=tenant AND e.state='posted' AND l.account_id=(p_arguments->>'account_id')::uuid AND(p_arguments->>'after_id' IS NULL OR l.id>(p_arguments->>'after_id')::uuid) AND(p_arguments->>'from_at' IS NULL OR e.effective_at>=(p_arguments->>'from_at')::timestamptz) AND(p_arguments->>'to_at' IS NULL OR e.effective_at<=(p_arguments->>'to_at')::timestamptz) ORDER BY l.id LIMIT lim)q;
 ELSIF op LIKE 'commerce.statements.%' THEN
  IF op='commerce.statements.list' THEN SELECT coalesce(jsonb_agg(to_jsonb(q)-'customer_id' ORDER BY q.id),'[]') INTO items FROM(SELECT * FROM public.sandy_commerce_statements WHERE customer_id=tenant AND(p_arguments->>'search' IS NULL OR strpos(lower(source_reference),lower(p_arguments->>'search'))>0) AND(p_arguments->>'account_id' IS NULL OR account_id=(p_arguments->>'account_id')::uuid) AND(p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) ORDER BY id LIMIT lim)q;
  ELSIF op='commerce.statements.import' THEN
   SELECT * INTO account FROM public.sandy_commerce_accounts WHERE id=(p_arguments->>'account_id')::uuid AND customer_id=tenant AND active FOR SHARE;IF account.id IS NULL THEN RAISE EXCEPTION 'owned_active_account_required' USING ERRCODE='P0409';END IF;
   INSERT INTO public.sandy_commerce_statements(customer_id,account_id,source_reference,content_sha256) VALUES(tenant,account.id,p_arguments->>'source_reference',encode(extensions.digest((p_arguments->'lines')::text,'sha256'),'hex')) RETURNING * INTO statement;
   FOR line IN SELECT value FROM jsonb_array_elements(p_arguments->'lines') LOOP INSERT INTO public.sandy_commerce_statement_lines(statement_id,external_reference,effective_at,amount_minor,description) VALUES(statement.id,line->>'external_reference',(line->>'effective_at')::timestamptz,public.sandy_commerce_minor(line->>'amount_minor',true),coalesce(line->>'description',''));END LOOP;changed:=true;
  ELSE SELECT * INTO statement FROM public.sandy_commerce_statements WHERE id=(p_arguments->>'statement_id')::uuid AND customer_id=tenant FOR UPDATE;IF statement.id IS NULL THEN RAISE EXCEPTION 'commerce_resource_not_found' USING ERRCODE='P0404';END IF;before_row:=public.sandy_commerce_statement_json(statement);IF op='commerce.statements.delete' THEN IF EXISTS(SELECT 1 FROM public.sandy_commerce_reconciliations WHERE statement_id=statement.id) THEN RAISE EXCEPTION 'reconciled_statement_is_retained' USING ERRCODE='P0409';END IF;DELETE FROM public.sandy_commerce_statements WHERE id=statement.id;item:=jsonb_build_object('id',statement.id,'state','deleted_unreconciled_manual_statement');statement.id:=NULL;changed:=true;END IF;
  END IF;IF statement.id IS NOT NULL THEN item:=public.sandy_commerce_statement_json(statement);END IF;
 ELSIF op LIKE 'commerce.reconciliation.%' THEN
  IF op='commerce.reconciliation.list' THEN SELECT coalesce(jsonb_agg(to_jsonb(q)-'customer_id'-'matches' ORDER BY q.id),'[]') INTO items FROM(SELECT * FROM public.sandy_commerce_reconciliations WHERE customer_id=tenant AND(p_arguments->>'statement_id' IS NULL OR statement_id=(p_arguments->>'statement_id')::uuid) AND(p_arguments->>'state' IS NULL OR state=p_arguments->>'state') AND(p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) ORDER BY id LIMIT lim)q;
  ELSIF op IN('commerce.reconciliation.preview','commerce.reconciliation.run') THEN
   SELECT * INTO statement FROM public.sandy_commerce_statements WHERE id=(p_arguments->>'statement_id')::uuid AND customer_id=tenant FOR SHARE;IF statement.id IS NULL THEN RAISE EXCEPTION 'commerce_resource_not_found' USING ERRCODE='P0404';END IF;
   item:=jsonb_build_object('statement_id',statement.id,'source_kind','manual_unverified','matches',public.sandy_commerce_proposed_matches(statement),'state','preview_internal','provider_verified',false);
   IF op='commerce.reconciliation.run' THEN INSERT INTO public.sandy_commerce_reconciliations(customer_id,statement_id,matches) VALUES(tenant,statement.id,item->'matches') RETURNING to_jsonb(sandy_commerce_reconciliations.*)-'customer_id'||jsonb_build_object('provider_verified',false) INTO item;changed:=true;END IF;
  ELSE SELECT * INTO recon FROM public.sandy_commerce_reconciliations WHERE id=(p_arguments->>'reconciliation_id')::uuid AND customer_id=tenant FOR UPDATE;IF recon.id IS NULL THEN RAISE EXCEPTION 'commerce_resource_not_found' USING ERRCODE='P0404';END IF;before_row:=to_jsonb(recon)-'customer_id';
   IF op='commerce.reconciliation.review' THEN
    SELECT * INTO statement FROM public.sandy_commerce_statements WHERE id=recon.statement_id AND customer_id=tenant;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(recon.matches)m WHERE m->>'state' IS DISTINCT FROM 'proposed_internal_match') THEN RAISE EXCEPTION 'all_statement_lines_require_unambiguous_internal_match' USING ERRCODE='P0409';END IF;
    IF recon.state<>'proposed_internal' OR recon.version<>(p_arguments->>'expected_version')::integer OR recon.matches IS DISTINCT FROM public.sandy_commerce_proposed_matches(statement) THEN RAISE EXCEPTION 'reconciliation_snapshot_changed' USING ERRCODE='P0409';END IF;
    UPDATE public.sandy_commerce_reconciliations SET state='reviewed_internal',version=version+1,reviewed_at=clock_timestamp() WHERE id=recon.id RETURNING * INTO recon;changed:=true;
   END IF;item:=to_jsonb(recon)-'customer_id'||jsonb_build_object('provider_verified',false);
  END IF;
 ELSIF op LIKE 'commerce.invoices.%' THEN
  IF op='commerce.invoices.list' THEN SELECT coalesce(jsonb_agg(public.sandy_commerce_invoice_json(q::public.sandy_commerce_invoices) ORDER BY q.id),'[]') INTO items FROM(SELECT * FROM public.sandy_commerce_invoices WHERE customer_id=tenant AND(p_arguments->>'search' IS NULL OR strpos(lower(counterparty_name||' '||external_reference||' '||coalesce(invoice_number,'')),lower(p_arguments->>'search'))>0) AND(p_arguments->>'state' IS NULL OR state=p_arguments->>'state') AND(p_arguments->>'forwarding_status' IS NULL OR forwarding_status=p_arguments->>'forwarding_status') AND(p_arguments->>'due_before' IS NULL OR due_at<=(p_arguments->>'due_before')::timestamptz) AND(p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) ORDER BY id LIMIT lim)q;
  ELSE
   IF op='commerce.invoices.create' THEN IF cfg.customer_id IS NULL THEN RAISE EXCEPTION 'commerce_configuration_required' USING ERRCODE='P0424';END IF;
    totals:=public.sandy_commerce_invoice_totals(p_arguments->'items',p_arguments->>'tax_minor',p_arguments->>'discount_minor');INSERT INTO public.sandy_commerce_invoices(customer_id,counterparty_name,external_reference,currency,minor_unit_exponent,items,subtotal_minor,tax_minor,discount_minor,total_minor,due_at) VALUES(tenant,p_arguments->>'counterparty_name',p_arguments->>'external_reference',cfg.currency,cfg.minor_unit_exponent,p_arguments->'items',(totals->>'subtotal_minor')::numeric,(totals->>'tax_minor')::bigint,(totals->>'discount_minor')::bigint,(totals->>'total_minor')::numeric,(p_arguments->>'due_at')::timestamptz) RETURNING * INTO invoice;changed:=true;
   ELSE
    SELECT * INTO invoice FROM public.sandy_commerce_invoices WHERE id=(p_arguments->>'invoice_id')::uuid AND customer_id=tenant FOR UPDATE;IF invoice.id IS NULL THEN RAISE EXCEPTION 'commerce_resource_not_found' USING ERRCODE='P0404';END IF;before_row:=public.sandy_commerce_invoice_json(invoice);
    IF op IN('commerce.invoices.update','commerce.invoices.issue','commerce.invoices.void') THEN IF invoice.version<>(p_arguments->>'expected_version')::integer THEN RAISE EXCEPTION 'invoice_version_changed' USING ERRCODE='P0409';END IF;END IF;
    IF op='commerce.invoices.update' THEN
     IF invoice.state<>'draft' THEN RAISE EXCEPTION 'only_draft_invoice_is_editable' USING ERRCODE='P0409';END IF;totals:=public.sandy_commerce_invoice_totals(p_arguments->'items',p_arguments->>'tax_minor',p_arguments->>'discount_minor');UPDATE public.sandy_commerce_invoices SET counterparty_name=p_arguments->>'counterparty_name',external_reference=p_arguments->>'external_reference',items=p_arguments->'items',subtotal_minor=(totals->>'subtotal_minor')::numeric,tax_minor=(totals->>'tax_minor')::bigint,discount_minor=(totals->>'discount_minor')::bigint,total_minor=(totals->>'total_minor')::numeric,due_at=(p_arguments->>'due_at')::timestamptz,version=version+1,updated_at=clock_timestamp() WHERE id=invoice.id RETURNING * INTO invoice;changed:=true;
    ELSIF op='commerce.invoices.issue' THEN
     IF invoice.state<>'draft' THEN RAISE EXCEPTION 'only_draft_invoice_can_issue' USING ERRCODE='P0409';END IF;SELECT * INTO cfg FROM public.sandy_commerce_configuration WHERE customer_id=tenant FOR UPDATE;IF cfg.customer_id IS NULL THEN RAISE EXCEPTION 'commerce_configuration_required' USING ERRCODE='P0424';END IF;
     UPDATE public.sandy_commerce_invoices SET state='issued_internal',invoice_number=cfg.invoice_prefix||'-'||cfg.next_invoice_number::text,version=version+1,updated_at=clock_timestamp() WHERE id=invoice.id RETURNING * INTO invoice;UPDATE public.sandy_commerce_configuration SET next_invoice_number=next_invoice_number+1,version=version+1,updated_at=clock_timestamp() WHERE customer_id=tenant;changed:=true;
    ELSIF op='commerce.invoices.void' THEN IF invoice.state='void' THEN RAISE EXCEPTION 'invoice_already_void' USING ERRCODE='P0409';END IF;UPDATE public.sandy_commerce_invoices SET state='void',version=version+1,updated_at=clock_timestamp() WHERE id=invoice.id RETURNING * INTO invoice;changed:=true;
    ELSIF op='commerce.invoices.reconcile_forwarding_status' THEN
     IF NOT EXISTS(SELECT 1 FROM public.email_messages WHERE id=(p_arguments->>'source_message_id')::uuid AND customer_id=tenant) THEN RAISE EXCEPTION 'owned_invoice_source_required' USING ERRCODE='P0404';END IF;
     SELECT CASE WHEN r.status IN('claimed','sending','submitted','verified','needs_review','failed') THEN r.status ELSE 'unknown' END INTO forward_state FROM public.sandy_email_action_receipts r WHERE r.source_message_id=(p_arguments->>'source_message_id')::uuid AND r.action_type='invoice_forward' ORDER BY r.updated_at DESC,r.id DESC LIMIT 1;
     UPDATE public.sandy_commerce_invoices SET source_message_id=(p_arguments->>'source_message_id')::uuid,forwarding_status=coalesce(forward_state,'not_observed'),version=version+1,updated_at=clock_timestamp() WHERE id=invoice.id RETURNING * INTO invoice;changed:=true;
    END IF;
   END IF;
   IF op='commerce.invoices.forwarding_status.get' THEN
    SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO items FROM(SELECT r.id,r.status,r.provider_message_id,r.created_at,r.updated_at FROM public.sandy_email_action_receipts r JOIN public.email_messages m ON m.id=r.source_message_id WHERE m.customer_id=tenant AND m.id=invoice.source_message_id AND r.action_type='invoice_forward' AND(p_arguments->>'after_id' IS NULL OR r.id>(p_arguments->>'after_id')::uuid) ORDER BY r.id LIMIT lim)q;item:=jsonb_build_object('id',invoice.id,'forwarding_status',invoice.forwarding_status,'payment_status','unverified','payment_executed',false,'invoice_source_correspondence_verified',false,'source_linkage','customer_asserted');
   ELSE item:=public.sandy_commerce_invoice_json(invoice);END IF;
  END IF;
 ELSIF op LIKE 'commerce.plans.%' THEN
  IF op='commerce.plans.list' THEN SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO items FROM(SELECT * FROM public.sandy_commerce_plans WHERE(p_arguments->>'search' IS NULL OR strpos(lower(code||' '||name||' '||description),lower(p_arguments->>'search'))>0) AND(p_arguments->>'active' IS NULL OR active=(p_arguments->>'active')::boolean) AND(p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) ORDER BY id LIMIT lim)q;
  ELSIF op='commerce.plans.create' THEN INSERT INTO public.sandy_commerce_plans(code,name,description) VALUES(p_arguments->>'code',p_arguments->>'name',p_arguments->>'description') RETURNING * INTO plan;changed:=true;
  ELSE SELECT * INTO plan FROM public.sandy_commerce_plans WHERE id=(p_arguments->>'plan_id')::uuid FOR UPDATE;IF plan.id IS NULL THEN RAISE EXCEPTION 'commerce_resource_not_found' USING ERRCODE='P0404';END IF;before_row:=to_jsonb(plan);
   IF op IN('commerce.plans.update','commerce.plans.archive') THEN IF plan.version<>(p_arguments->>'expected_version')::integer THEN RAISE EXCEPTION 'plan_version_changed' USING ERRCODE='P0409';END IF;UPDATE public.sandy_commerce_plans SET name=coalesce(p_arguments->>'name',name),description=coalesce(p_arguments->>'description',description),active=CASE WHEN op='commerce.plans.archive' THEN false ELSE active END,version=version+1,updated_at=clock_timestamp() WHERE id=plan.id RETURNING * INTO plan;changed:=true;END IF;
  END IF;IF plan.id IS NOT NULL THEN item:=to_jsonb(plan);END IF;
 ELSIF op LIKE 'commerce.prices.%' THEN
  IF op='commerce.prices.list' THEN IF NOT EXISTS(SELECT 1 FROM public.sandy_commerce_plans WHERE id=(p_arguments->>'plan_id')::uuid) THEN RAISE EXCEPTION 'commerce_resource_not_found' USING ERRCODE='P0404';END IF;SELECT coalesce(jsonb_agg(to_jsonb(q)||jsonb_build_object('unit_minor',q.unit_minor::text) ORDER BY q.id),'[]') INTO items FROM(SELECT * FROM public.sandy_commerce_prices WHERE plan_id=(p_arguments->>'plan_id')::uuid AND(p_arguments->>'currency' IS NULL OR currency=p_arguments->>'currency') AND(p_arguments->>'interval' IS NULL OR interval=p_arguments->>'interval') AND(p_arguments->>'active' IS NULL OR active=(p_arguments->>'active')::boolean) AND(p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) ORDER BY id LIMIT lim)q;
  ELSIF op='commerce.prices.create' THEN IF NOT EXISTS(SELECT 1 FROM public.sandy_commerce_plans WHERE id=(p_arguments->>'plan_id')::uuid AND active) THEN RAISE EXCEPTION 'active_plan_required' USING ERRCODE='P0409';END IF;INSERT INTO public.sandy_commerce_prices(plan_id,currency,minor_unit_exponent,unit_minor,interval) VALUES((p_arguments->>'plan_id')::uuid,p_arguments->>'currency',(p_arguments->>'minor_unit_exponent')::integer,public.sandy_commerce_minor(p_arguments->>'unit_minor'),p_arguments->>'interval') RETURNING * INTO price;changed:=true;
  ELSE SELECT * INTO price FROM public.sandy_commerce_prices WHERE id=(p_arguments->>'price_id')::uuid FOR UPDATE;IF price.id IS NULL THEN RAISE EXCEPTION 'commerce_resource_not_found' USING ERRCODE='P0404';END IF;before_row:=to_jsonb(price)||jsonb_build_object('unit_minor',price.unit_minor::text);IF op='commerce.prices.archive' THEN UPDATE public.sandy_commerce_prices SET active=false WHERE id=price.id RETURNING * INTO price;changed:=true;END IF;
  END IF;IF price.id IS NOT NULL THEN item:=to_jsonb(price)||jsonb_build_object('unit_minor',price.unit_minor::text,'provider_price_created',false);END IF;
 ELSIF op LIKE 'commerce.entitlements.%' THEN
  IF op='commerce.entitlements.list' THEN SELECT coalesce(jsonb_agg(to_jsonb(q)-'customer_id' ORDER BY q.id),'[]') INTO items FROM(SELECT * FROM public.sandy_commerce_entitlements WHERE customer_id=tenant AND(p_arguments->>'feature_key' IS NULL OR feature_key=p_arguments->>'feature_key') AND(p_arguments->>'enabled' IS NULL OR(revoked_at IS NULL AND expires_at>clock_timestamp())=(p_arguments->>'enabled')::boolean) AND(p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) ORDER BY id LIMIT lim)q;
  ELSIF op='commerce.entitlements.check' THEN SELECT coalesce(bool_or(revoked_at IS NULL AND expires_at>clock_timestamp()),false) INTO changed FROM public.sandy_commerce_entitlements WHERE customer_id=tenant AND feature_key=p_arguments->>'feature_key';item:=jsonb_build_object('feature_key',p_arguments->>'feature_key','enabled',changed,'source','explicit_internal_entitlement','payment_verified',false);changed:=false;
  ELSE
   effect_tenant:=(p_arguments->>'customer_id')::uuid;IF NOT EXISTS(SELECT 1 FROM public.email_customers WHERE id=effect_tenant) THEN RAISE EXCEPTION 'commerce_resource_not_found' USING ERRCODE='P0404';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('sandy-commerce-state:'||effect_tenant::text,0));SELECT to_jsonb(e)-'customer_id' INTO before_row FROM public.sandy_commerce_entitlements e WHERE customer_id=effect_tenant AND feature_key=p_arguments->>'feature_key' FOR UPDATE;
   IF op='commerce.entitlements.grant' THEN IF(p_arguments->>'expires_at')::timestamptz<=clock_timestamp() OR(p_arguments->>'expires_at')::timestamptz>clock_timestamp()+interval '366 days' THEN RAISE EXCEPTION 'bounded_entitlement_expiry_required' USING ERRCODE='22023';END IF;INSERT INTO public.sandy_commerce_entitlements(customer_id,feature_key,expires_at,reason) VALUES(effect_tenant,p_arguments->>'feature_key',(p_arguments->>'expires_at')::timestamptz,p_arguments->>'reason') ON CONFLICT(customer_id,feature_key) DO UPDATE SET expires_at=excluded.expires_at,revoked_at=NULL,reason=excluded.reason,version=sandy_commerce_entitlements.version+1,updated_at=clock_timestamp() RETURNING to_jsonb(sandy_commerce_entitlements.*)-'customer_id' INTO item;
   ELSE UPDATE public.sandy_commerce_entitlements SET revoked_at=clock_timestamp(),reason=p_arguments->>'reason',version=version+1,updated_at=clock_timestamp() WHERE customer_id=effect_tenant AND feature_key=p_arguments->>'feature_key' RETURNING to_jsonb(sandy_commerce_entitlements.*)-'customer_id' INTO item;IF item IS NULL THEN RAISE EXCEPTION 'commerce_resource_not_found' USING ERRCODE='P0404';END IF;END IF;changed:=true;
  END IF;
 ELSIF op='commerce.processor.capabilities' THEN item:=jsonb_build_object('configured_processor',NULL,'internal_ledger',true,'processor_payments',false,'refunds',false,'payouts',false,'tax_attestation',false,'processor_entitlements',false,'required_configuration',jsonb_build_array('explicit_processor_selection','authorized_merchant_fixture','commercial_currency_and_tax_policy','provider_secret_reference','provider_test_session'),'payment_executed',false,'provider_verified',false);
 ELSIF op='commerce.audit.list' THEN SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO items FROM(SELECT e.admission_id AS id,e.operation,e.actor_kind,e.created_at,a.request_id,a.state,a.result_sha256 FROM public.sandy_commerce_effects e JOIN public.sandy_api_execution_admissions a ON a.id=e.admission_id WHERE e.customer_id=tenant AND(p_arguments->>'operation' IS NULL OR e.operation=p_arguments->>'operation') AND(p_arguments->>'from_at' IS NULL OR e.created_at>=(p_arguments->>'from_at')::timestamptz) AND(p_arguments->>'to_at' IS NULL OR e.created_at<=(p_arguments->>'to_at')::timestamptz) AND(p_arguments->>'after_id' IS NULL OR e.admission_id>(p_arguments->>'after_id')::uuid) ORDER BY e.admission_id LIMIT lim)q;
 ELSE RAISE EXCEPTION 'unimplemented_commerce_contract' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(items)=lim AND items->-1 ? 'id' THEN cursor:=items->-1->>'id';END IF;
 result:=public.sandy_commerce_bounded_result(item,items,changed,cursor,jsonb_array_length(items)>=lim);
 IF admission.is_mutation THEN PERFORM public.sandy_product_record_mutation(admission.id,before_row,CASE WHEN item IS NOT NULL THEN item ELSE items END);INSERT INTO public.sandy_commerce_effects VALUES(admission.id,effect_tenant,op,CASE WHEN config->>'authorization'='owner' THEN 'owner' ELSE 'tenant' END,clock_timestamp());END IF;
 proof:=public.sandy_api_finish_execution(admission.id,CASE WHEN admission.is_mutation THEN 'accepted' ELSE 'succeeded' END,200,NULL,encode(extensions.digest(result::text,'sha256'),'hex'));IF proof->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'commerce_receipt_not_persisted';END IF;
 INSERT INTO public.sandy_commerce_results VALUES(admission.id,result,true,clock_timestamp());RETURN jsonb_build_object('ok',true,'admission_id',admission.id,'request_id',admission.request_id,'request_state',CASE WHEN admission.is_mutation THEN 'accepted' ELSE 'observed' END,'executed',true,'reconciliation_required',admission.is_mutation,'result',result);
EXCEPTION WHEN SQLSTATE 'P0413' THEN RETURN public.sandy_commerce_fail_internal(p_admission_id,p_grant_id,p_arguments,p_canonical_arguments,p_channel,'commerce_response_record_too_large',413);
 WHEN SQLSTATE 'P0404' THEN RETURN public.sandy_commerce_fail_internal(p_admission_id,p_grant_id,p_arguments,p_canonical_arguments,p_channel,'commerce_resource_not_found',404);
 WHEN SQLSTATE 'P0409' THEN RETURN public.sandy_commerce_fail_internal(p_admission_id,p_grant_id,p_arguments,p_canonical_arguments,p_channel,'commerce_state_or_version_conflict',409);
 WHEN SQLSTATE 'P0424' THEN RETURN public.sandy_commerce_fail_internal(p_admission_id,p_grant_id,p_arguments,p_canonical_arguments,p_channel,'commerce_configuration_required',424);
 WHEN data_exception OR unique_violation OR check_violation OR not_null_violation OR foreign_key_violation THEN RETURN public.sandy_commerce_fail_internal(p_admission_id,p_grant_id,p_arguments,p_canonical_arguments,p_channel,'invalid_commerce_state_or_arguments',400);
END $$;

CREATE FUNCTION public.sandy_commerce_get_receipt(p_request_id uuid,p_channel text DEFAULT 'api') RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE admission public.sandy_api_execution_admissions%ROWTYPE;principal jsonb;result jsonb;dispatched boolean;
BEGIN
 IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN RETURN jsonb_build_object('ok',false,'error','authenticated_customer_session_required','http_status',401);END IF;
 IF p_channel IS NULL OR p_channel NOT IN ('api','mcp') OR NOT EXISTS(SELECT 1 FROM public.sandy_operation_registry r JOIN public.sandy_commerce_contracts c ON c.operation=r.operation WHERE r.operation='commerce.executions.get' AND r.error_contract->>'requires_approval'='false' AND r.error_contract->>'api_key_delegable'='false' AND r.handler='sandy-commerce-ledger-api' AND r.api_exposed AND(p_channel='api' OR r.ai_exposed) AND r.verified AND r.error_contract->>'contract_sha256'=c.contract->>'contract_sha256' AND r.input_schema=c.contract->'input_schema' AND r.output_schema=c.contract->'output_schema') THEN RETURN jsonb_build_object('ok',false,'error','product_receipt_not_enabled_or_verified','http_status',403);END IF;
 SELECT * INTO admission FROM public.sandy_api_execution_admissions WHERE actor_id=auth.uid() AND request_id=p_request_id AND operation IN(SELECT operation FROM public.sandy_commerce_contracts);
 IF admission.id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','product_execution_not_found','http_status',404);END IF;
 principal:=public.sandy_commerce_principal(admission.operation);
 IF principal IS NULL OR admission.tenant_id IS DISTINCT FROM (principal->>'tenant_id')::uuid THEN RETURN jsonb_build_object('ok',false,'error','product_identity_or_grant_required','http_status',403);END IF;
 SELECT r.result,r.executed INTO result,dispatched FROM public.sandy_commerce_results r WHERE r.admission_id=admission.id;
 RETURN jsonb_build_object('ok',true,'admission_id',admission.id,'request_id',admission.request_id,'request_state',CASE WHEN result IS NOT NULL THEN 'replayed' ELSE 'unknown' END,'executed',CASE WHEN admission.state IN ('admitted','rejected') THEN false WHEN admission.state IN ('accepted','succeeded','failed') THEN dispatched ELSE NULL END,'result',public.sandy_commerce_result(jsonb_build_object('operation',admission.operation,'state',admission.state,'result',result,'redispatch_permitted',false,'created_at',admission.created_at,'finished_at',admission.finished_at)),'reconciliation_required',admission.state IN ('consumed','unknown','accepted'));
END $$;

DO $$DECLARE f record;BEGIN FOR f IN SELECT p.oid::regprocedure AS signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'sandy_commerce_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,service_role',f.signature);END LOOP;END $$;
GRANT EXECUTE ON FUNCTION public.sandy_commerce_admit(text,jsonb,text,uuid,text,uuid),public.sandy_commerce_execute(uuid,uuid,jsonb,text,text),public.sandy_commerce_get_receipt(uuid,text) TO authenticated;
COMMIT;
